nginx_include:
# Include in the selected http context: existing active ingress or the office-only wrapper.
# office-v5-layout-shift-06 and 19011 are rendered by packaging/preflight.
server {
    listen 192.168.100.221:19000;
    server_name 192.168.100.221 hereww.i234.me;
    allow all;
    if ($host !~* "^(192\.168\.100\.221|hereww\.i234\.me)$") { return 444; }
    autoindex off;
    default_type application/octet-stream;
    types {
        text/html html; text/css css; application/javascript js mjs;
        application/json json; image/png png; image/webp webp;
        image/svg+xml svg; font/woff woff; font/woff2 woff2; font/ttf ttf;
    }
    add_header X-Content-Type-Options nosniff always;
    add_header X-Frame-Options SAMEORIGIN always;
    # GET implicitly permits HEAD in nginx. Every other method is denied.
    location = / {
        limit_except GET { deny all; }
        root /opt/star-office-ui/releases/office-v5-layout-shift-06/public;
        try_files /static/releases/office-v5-layout-shift-06/office/index.html =404;
        add_header Cache-Control "no-store" always;
    }
    location ^~ /static/releases/office-v5-layout-shift-06/ {
        limit_except GET { deny all; }
        root /opt/star-office-ui/releases/office-v5-layout-shift-06/public;
        try_files $uri =404;
        add_header Cache-Control "public, max-age=31536000, immutable" always;
        add_header X-Content-Type-Options nosniff always;
    }
    location = /api/office/snapshot {
        limit_except GET { deny all; }
        proxy_pass http://127.0.0.1:19011;
        proxy_set_header Host 192.168.100.221:19000;
        proxy_set_header X-Forwarded-Proto http;
        proxy_set_header X-Forwarded-For $remote_addr;
        proxy_hide_header Set-Cookie;
        add_header Cache-Control "no-store" always;
    }
    location = /health {
        limit_except GET { deny all; }
        proxy_pass http://127.0.0.1:19011;
        proxy_set_header Host 192.168.100.221:19000;
        proxy_set_header X-Forwarded-Proto http;
        proxy_set_header X-Forwarded-For $remote_addr;
        proxy_hide_header Set-Cookie;
    }
    location / { return 404; }
}
server {
    listen 192.168.100.221:19443 ssl;
    server_name 192.168.100.221;
    allow 192.168.100.0/24;
    deny all;
    if ($host != 192.168.100.221) { return 444; }
    ssl_certificate /opt/star-office-ui/private/office-server-chain.pem;
    ssl_certificate_key /opt/star-office-ui/private/office-server.key;
    ssl_protocols TLSv1.2 TLSv1.3;
    autoindex off;
    default_type application/octet-stream;
    types {
        text/html html; text/css css; application/javascript js mjs;
        application/json json; image/png png; image/webp webp;
        image/svg+xml svg; font/woff woff; font/woff2 woff2; font/ttf ttf;
    }
    client_max_body_size 1m;
    add_header X-Content-Type-Options nosniff always;
    add_header X-Frame-Options SAMEORIGIN always;
    location = / {
        limit_except GET { deny all; }
        root /opt/star-office-ui/releases/office-v5-layout-shift-06/public;
        try_files /static/releases/office-v5-layout-shift-06/office/index.html =404;
        add_header Cache-Control "no-store" always;
    }
    location = /admin {
        limit_except GET { deny all; }
        # The extensionless request URI does not inherit the alias .html type.
        # An explicit type is required to render the login page, not download it.
        default_type text/html;
        alias /opt/star-office-ui/releases/office-v5-layout-shift-06/public/static/releases/office-v5-layout-shift-06/office/admin.html;
        add_header Cache-Control "no-store" always;
        add_header X-Content-Type-Options nosniff always;
        add_header X-Frame-Options SAMEORIGIN always;
    }
    location ^~ /static/releases/office-v5-layout-shift-06/ {
        limit_except GET { deny all; }
        root /opt/star-office-ui/releases/office-v5-layout-shift-06/public;
        try_files $uri =404;
        add_header Cache-Control "public, max-age=31536000, immutable" always;
        add_header X-Content-Type-Options nosniff always;
    }
    location ^~ /local/ { return 404; }
    # Auth decisions are made by the deployed WSGI guard, not HTTP Basic auth.
    # It uses authenticated config/session APIs; legacy writes ALSO require
    # same-origin + current CSRF token. Unintegrated backend fails closed.
    location / {
        proxy_pass http://127.0.0.1:19011;
        proxy_set_header Host 192.168.100.221:19443;
        proxy_set_header X-Forwarded-Host 192.168.100.221:19443;
        proxy_set_header X-Forwarded-Proto https;
        proxy_set_header X-Forwarded-For $remote_addr;
        proxy_set_header Connection "";
        proxy_http_version 1.1;
        add_header Cache-Control "no-store" always;
    }
}

nginx_wrapper:
# Office-only ingress when the host has no active shared nginx master.
# Do not start/reload /www/server/nginx/conf/nginx.conf or unrelated vhosts.
user nobody;
worker_processes 2;
pid /run/star-office-ingress/nginx.pid;
error_log /var/log/star-office-ingress/error.log warn;
events { worker_connections 1024; }
http {
    # The verified host binary includes ngx_lua; this is its installed library path.
    lua_package_path "/www/server/nginx/lib/lua/?.lua;;";
    server_tokens off;
    sendfile on;
    keepalive_timeout 15;
    client_header_timeout 10;
    client_body_timeout 10;
    log_format office '$remote_addr "$request_method $uri" $status $body_bytes_sent $request_time';
    access_log /var/log/star-office-ingress/access.log office;
    client_body_temp_path /var/cache/star-office-ingress/client;
    proxy_temp_path /var/cache/star-office-ingress/proxy;
    fastcgi_temp_path /var/cache/star-office-ingress/fastcgi;
    uwsgi_temp_path /var/cache/star-office-ingress/uwsgi;
    scgi_temp_path /var/cache/star-office-ingress/scgi;
    include /opt/star-office-ui/ingress/office-public-employee.conf;
}
